@startuml

class HBMS {
  + CalculateReliabilityRating(traveller: Traveller): float
}

class Traveller {
  + Name : string
  + BillingInformation : string
  + CompanyName : string
  + Address : string
  + TravelPreferences : string[]
}

class SearchCriteria {
  + City : string
  + ArrivalDate : date
  + DepartureDate : date
  + NumberOfRooms : int
  + RoomType : string
  + MinimumRating : int
  + MaxCostPerNight : float
  + AdditionalPreferences : string[]
}

class PreliminaryBooking {
  + BookingIdentifier : string
  + Price : float
  + CityArea : string
  + HotelRating : int
  + KeyPreferences : string[]
}

class SpecialOffer {
  + Price : float
}

class Booking {
  + BookingIdentifier : string
  + CancellationDeadline : date
  + IsPrePaid : boolean
  + IsConfirmed : boolean
}

class Hotel {
  + Name : string
  + Address : string
  + Rating : int
}

class HotelChain {
  + Name : string
}

class RoomType {
  + Type : string
}

class CreditCardInfo {
  + CardNumber : string
  + ExpiryDate : date
}

Traveller "1" -- "*" PreliminaryBooking : creates
Traveller "1" -- "*" Booking : makes
Traveller "1" -- "*" SpecialOffer : receives
Traveller "1" -- "0..1" CreditCardInfo : provides
Traveller "1" -- "*" Booking : has past bookings

HBMS "1" -- "*" PreliminaryBooking : manages
HBMS "1" -- "*" SpecialOffer : sends
HBMS "1" -- "*" Booking : manages
HBMS "1" -- "*" Hotel : lists

Hotel "0..1" -- "1" HotelChain : run by
Hotel "1" -- "*" RoomType : offers
Hotel "1" -- "1" Address : located at
Hotel "1" -- "*" Booking : confirms

Booking "1" -- "1" RoomType : contains
Booking "1" -- "1" Hotel : booked at
Booking "1" -- "1" CreditCardInfo : paid with

PreliminaryBooking "1" -- "0..*" SpecialOffer : generates competition

@enduml

